files.summarise.sh:
#!/bin/sh
# Summarise a greenhouse log: min, max and average temperature and humidity.
# Usage: sh summarise.sh LOG_FILE
file="$1"
[ -r "$file" ] || { echo "cannot read log file" >&2; exit 2; }
awk -F, '
  NR == 1 { tmin = tmax = $2; hmin = hmax = $3 }
  {
    if ($2 < tmin) tmin = $2
    if ($2 > tmax) tmax = $2
    if ($3 < hmin) hmin = $3
    if ($3 > hmax) hmax = $3
    tsum += $2; hsum += $3; n++
  }
  END {
    printf "temperature min %.1f max %.1f avg %.1f\n", tmin, tmax, tsum / n
    printf "humidity    min %.1f max %.1f avg %.1f\n", hmin, hmax, hsum / n
  }
' "$file"

files.check.sh:
#!/bin/sh
# Summarise bed A and compare with the expected summary.
sh summarise.sh logs/bed-a.csv | diff - logs/expected-bed-a.txt && echo "bed A ok"
